using System.Runtime.InteropServices;
using IECODE.Ffi.Native;
unsafe {
    delegate* unmanaged<byte*> version = &IecodeNative.CoreVersion;
    nuint original = (nuint)version();
    GC.Collect(2, GCCollectionMode.Forced, true, true);
    bool versionPointerMoved = (nuint)version() != original;
    byte* input = (byte*)NativeMemory.AllocZeroed(272);
    new ReadOnlySpan<byte>("CRILAYLA"u8.ToArray()).CopyTo(new Span<byte>(input, 8));
    input[16] = 0xA5;
    byte* output = null;
    int length = 0;
    delegate* unmanaged<byte*, int, byte**, int*, int> decompress = &IecodeNative.CrilaylaDecompress;
    int status = decompress(input, 16, &output, &length);
    bool readPastDeclaredLength = output != null && output[0] == 0xA5;
    Console.WriteLine($"version_pointer_moved={versionPointerMoved}; truncated_status={status}; output_length={length}; read_past_declared_length={readPastDeclaredLength}");
    NativeMemory.Free(output);
    NativeMemory.Free(input);
}

#include "iecode/compression/crilayla.h"
#include <vector>
