int main() {
    std::vector<uint8_t> bytes(273, 0);
    std::memcpy(bytes.data(), "CRILAYLA", 8);
    bytes[8] = 32;
    bytes[12] = 1;
    auto output = iecode::compression::crilayla_decompress(bytes);
    std::cout << "exhausted_stream_accepted=" << (!output.empty()) << "; output_size=" << output.size() << '\n';
}

